/** Detailed command help shown by `engram help <topic>`. */
export type CommandTopicHelp = {
  title: string;
  summary: string;
  useCases: string[];
  examples: string[];
  notes?: string[];
  aliases?: string[];
};

export const COMMAND_TOPICS: Record<string, CommandTopicHelp> = {
  '--version': topic('engram --version', 'Print the current Engram CLI version.', ['Check which build is installed before reporting an issue.'], ['engram --version', 'engram -v'], ['The runtime VERSION is generated from package.json during build.'], ['version', '-v']),
  inject: topic('engram inject', 'Create or reconcile memory roots and install compact Codex skillset instructions by default.', ['Start using Engram in a repository.', 'Create a global-only memory store without installing `.agents/.engram` in the current workspace.', 'Repair missing Engram-owned files and folders after upgrades.', 'Choose a workspace-specific global memory path.', 'Choose whether normal saves default to workspace, global, or both.', 'Give agents terse Engram operating instructions immediately.', 'Configure shared global memory through a Git remote.', 'Create `.agents/.engram` as a submodule when a team wants memory versioned separately.'], ['engram inject', 'engram inject --scope workspace', 'engram inject --scope both --global-path ~/Documents/engram', 'engram inject --global-only --global-path ~/Documents/engram', 'engram inject --no-skillset', 'engram inject --skillset all', 'engram inject --no-global', 'engram inject --global-path ~/Documents/engram', 'engram inject --submodule', 'engram inject --global-remote https://github.com/example/team-engram.git'], ['Fresh workspace installs default normal saves to `both`; if no global memory is configured yet, writes fall back to workspace until a global path exists.', 'When global memory is configured, inject creates or selects a user default profile for that global root.', 'Default skillset target is `codex`; existing human-authored instruction files are skipped.', '`--global-only` writes a user-level pointer to the global folder, sets default saves to global, and skips local skillset installation.', 'Repeated inject preserves memory files, hashes, changelog data, and existing save targets while refreshing generated scaffolding.', 'Interactive inject prompts for submodule setup, optional global path, then optional global remote.']),
  help: topic('engram help', 'Show command help. Add a topic for deeper command-specific guidance.', ['Learn a command before running it.', 'Find examples for aliases, save flows, or operational commands.'], ['engram help', 'engram help set-role', 'engram -h save-session', 'engram save -h'], ['The overview stays short; topic help explains intent and examples.'], ['h', '-h']),
  author: topic('engram author', 'Manage global and workspace Engram author identities.', ['Inspect identity resolution.', 'Set or remove an Engram-owned profile.', 'Preview and confirm global Git synchronization.', 'Preview and confirm legacy memory author migration.'], ['engram author show', 'engram author set --name "Jane Doe" --email "jane@example.com"', 'engram author set --scope workspace --name "Workspace Jane" --email "jane@work.com"', 'engram author sync-git-global --plan', 'engram author migrate-memories --scope both --plan'], ['Usage: engram author [show|set|unset|sync-git-global|migrate-memories]', 'Workspace overrides never modify global Git configuration.', 'Settings affect future memories only unless migration is explicitly confirmed.', 'New memories store author_name only; set `memory.include_author_email true` to also write author_email.']),
  'author show': topic('engram author show', 'Show global, workspace, Git fallback, and resolved identity.', ['Verify which identity new memories and Engram commits use.'], ['engram author show', 'engram author show --scope global', 'engram author show --json'], ['Usage: engram author show [--scope global|workspace] [--json]']),
  'author set': topic('engram author set', 'Save a global or workspace Engram author profile.', ['Set the default author for future memories.', 'Override author identity in one workspace.'], ['engram author set --name "Jane Doe" --email "jane@example.com"', 'engram author set --scope workspace --name "Jane Doe" --email "jane@work.com"'], ['Usage: engram author set [--scope global|workspace] --name <name> --email <email>', 'The default scope is global.']),
  'author unset': topic('engram author unset', 'Remove one Engram author profile.', ['Remove a workspace override.', 'Remove the global Engram profile and fall back to Git.'], ['engram author unset --scope workspace', 'engram author unset --scope global'], ['Usage: engram author unset --scope global|workspace', 'The scope is required.']),
  'author sync-git-global': topic('engram author sync-git-global', 'Synchronize the global Engram profile to global Git config.', ['Preview exact user.name and user.email changes.', 'Apply only after explicit confirmation.'], ['engram author sync-git-global --plan', 'engram author sync-git-global --confirm'], ['Usage: engram author sync-git-global [--plan|--confirm] [--json]', 'Only the global Engram profile can be synchronized.', 'Failures restore the previous global Git values.']),
  'author migrate-memories': topic('engram author migrate-memories', 'Backfill author_name in active legacy memories, or strip author_email from memory files.', ['Preview eligible files.', 'Migrate workspace, global, or both scopes with backups.'], ['engram author migrate-memories --plan', 'engram author migrate-memories --scope workspace --confirm', 'engram author migrate-memories --scope both --confirm', 'engram author migrate-memories --strip-email --scope both'], ['Usage: engram author migrate-memories [--scope workspace|global|both] [--strip-email] [--plan|--confirm] [--json]', 'Migration preserves Markdown bodies and writes .pre-author-v3.bak backups under backups/author-v3/.', '`--strip-email` removes author_email (and legacy author: emails) from frontmatter; it plans by default and writes only with `--confirm`, keeping backups under backups/author-strip-email-<date>/.']),
  llm: topic('engram llm', 'Print the packaged AI agent usage guide from `llm.txt`.', ['Give an AI agent a stable, package-local summary of how to use Engram.', 'Answer "how should my agent use Engram?" without relying on online docs.', 'Inspect the same agent-facing guide that ships in the npm package.'], ['engram llm', 'engram help llm'], ['The command is read-only and can run before `engram inject`.', '`llm.txt` is curated, committed, and included in the published package.', 'For full human documentation, use the README and documentation folder.']),
  entry: topic('engram entry', 'Open a browser web UI showing runtime configuration, memory roots, and global Git state.', ['Debug which global memory folder is active.', 'Confirm configured vs detected global Git branch.', 'Check whether live sync, roles, or rule variants are enabled.', 'Inspect all resolved config values in a clean visual interface.'], ['engram entry', 'engram e', 'engram entry --host-only'], ['Starts a local HTTP server and opens the browser automatically.', 'Use --host-only to start the server without opening a browser tab.', 'Click any row to copy its value.', 'Click Close or close the browser tab to stop the server.', 'Use this before changing Git remotes or diagnosing unexpected memory routing.'], ['e']),
  profile: topic('engram profile', 'Manage isolated global memory profiles for company, personal, and team contexts.', ['Create separate global memory roots so company and personal memory do not share one pool.', 'Set a user default profile for uninitialized folders.', 'Set a workspace default profile for initialized repositories.', 'Run a one-off command against another profile with `--profile <name>`.', 'Merge one profile into another while reporting duplicate candidates.'], ['engram profile create personal --global-path ~/Documents/engram-personal --use', 'engram profile create company --global-path ~/Documents/engram-company', 'engram profile use company --workspace', 'engram --profile personal load "my preferences"', 'engram save --profile personal --scope global knowledge "My side project uses pnpm."', 'engram profile merge company personal --dry-run', 'engram profile merge --from-profile company --to-profile personal'], ['Profiles select the active global memory root; workspace and global remain the two memory scopes.', 'When a workspace default profile is set, it wins over the user default in that folder.', 'If `--profile` selects a different profile than the workspace default, workspace memory is disabled for that command to avoid cross-profile reads or writes.', 'Profile registries live in the user config directory, while workspace configs store only a default profile name.', 'Profile merge copies active `rules/`, `skills/`, and `knowledge/` memories from the source profile into the target profile and skips duplicates unless `--force` is passed.'], ['pf']),
  'update-global-folder': topic('engram update-global-folder', 'Update the configured global memory folder and optionally move an existing global root.', ['Point Engram at a new global memory folder without moving old files.', 'Rename the global root folder while preserving memory files, Git history, hashes, and sidecars.', 'Move global memory from an explicit old path when the active config is stale or overridden.', 'Let slash/chat users say natural phrases such as "set global memory path to ..." or "move global folder from ... to ...".', 'Replace an empty/generated destination scaffold with the moved root.', 'Refuse to overwrite a destination that already contains memory or user files.'], ['engram update-global-folder ~/Documents/engram-global', 'engram ugf ~/Documents/engram-renamed --move-from-path ~/Documents/engram', 'engram set global memory path to ~/Documents/engram-global', 'engram move global folder from ~/Documents/engram to ~/Documents/engram-renamed', 'engram update-global-folder F:\\engram\\new-global --move-from-path F:\\engram\\old-global'], ['Without `--move-from-path`, the command updates saved config and reconciles the target folder; existing memory stays where it is.', 'Natural phrases normalize to `update-global-folder`; supported verbs include update, set, change, move, and rename when followed by global folder/path/root wording.', 'With `--move-from-path`, Engram moves the whole old root before updating config. If the destination is missing, it renames the folder so `.git`, custom files, hashes, indexes, and sidecars are preserved.', 'If the destination exists with only generated scaffold files, Engram clears that scaffold and moves the old root into place.', 'If the destination already contains real memory or user files, the command fails before moving anything to avoid overwrites.', '`ENGRAM_GLOBAL_DIR` overrides saved config; when it points somewhere else, the command reports a warning.'], ['ugf']),
  completion: topic('engram completion', 'Print shell completion scripts for Tab suggestions.', ['Enable command suggestions in bash, zsh, or PowerShell.', 'Discover subcommands and common flags faster.'], ['source <(engram completion bash)', 'source <(engram completion zsh)', 'engram completion powershell', 'engram c bash'], ['The command prints the script; add it to your shell startup file when you want it loaded every session.'], ['c']),
  upgrade: topic('engram upgrade', 'Recommend the latest package update and refresh generated Engram assets.', ['Get a quick, copyable npm update recommendation.', 'Refresh initialized workspace HELP.md, memory indexes, graphs, vector sidecars, and generated workspace skillsets without a separate maintenance command.', 'Preview global memory and global skillset refreshes before writing.', 'Refresh Engram-owned global agent rules after an Engram release.', 'Limit the refresh to memory, global skillsets, or one target agent.'], ['engram upgrade', 'engram upgrade --plan', 'engram upgrade --latest', 'engram upgrade --latest --plan', 'engram upgrade --latest --review', 'engram upgrade --latest --yes', 'engram upgrade --migrate-memories', 'engram upgrade --latest --no-migrate-memories', 'engram upgrade --configs-only', 'engram upgrade --global-skillsets-only', 'engram upgrade --target codex', 'engram up --plan'], ['Default output stays conservative and shows the quick package update command.', 'After an npm package update, normal Engram commands run a quiet one-time auto-upgrade for already-initialized roots; pass `--no-auto-upgrade` or set `ENGRAM_NO_AUTO_UPGRADE=1` to skip it.', '`engram upgrade` reconciles release-to-release memory schema changes from v0.0.8 onward by refreshing generated HELP.md, indexes, graph files, and eligible vector sidecars.', '`engram upgrade` refreshes existing generated workspace skillsets and preserves human-authored files.', '`engram upgrade --latest` uses the shared workspace/global upgrade inventory. It safely migrates active v1/v2 memories, updates only provably Engram-owned files or managed blocks, preserves user-authored bytes, reports ambiguous mixed files as conflicts, and rebuilds optional vector sidecars fail-open after durable changes. `--plan` renders the same plan used by Entry Web UI before any write. Use `--review` to resolve conflicts with Current/Proposed/Diff semantics; `E` opens `$VISUAL`, then `$EDITOR`, then a platform editor fallback. Review decisions resume by plan/source hash. `--yes` applies only when every conflict is already reviewed and never invents a decision.', 'Use `--migrate-memories` to run the same memory migration without linked-artifact overwrite, or `--no-migrate-memories` to opt out when using `--latest`. `--plan` previews eligible, current, and failed files without writing.', '`engram upgrade --configs-only` limits the refresh to workspace agent configs (linked + detected) and skips memory, hooks, package recommendation, and global skillset operations. Cannot be combined with `--memory-only` or `--global-skillsets-only`.', '`engram inject` also refreshes generated workspace HELP.md and skillsets as part of scaffold reconciliation.', '`--self` attempts `npm install -g @the-long-ride/engram@latest` from the CLI, then still recommends running `engram upgrade` again under the new version.', '`--plan` and `--dry-run` do not write files.'], ['up']),
  save: topic('engram save', 'Propose one durable memory and save it only after A/B/C approval.', ['Capture a user correction as a rule.', 'Capture an objective project fact as knowledge.', 'Capture a repeatable procedure as a workflow/skill.', 'Attach role tags with `--role` or `--roles` so routing can filter frontend, backend, docs, or security memory.', 'Add a `task_type:*` tag with `--task-type <task>` or let Engram classify the current save text.', 'Preview related existing memories that may be dependencies or duplicates before saving.', 'Override the configured save target for a single save with `--scope workspace`, `--scope global`, or `--scope both`.', 'Save into another profile global root with `--profile <name> --scope global`.', 'Let Engram auto-detect the type from concise text.'], ['engram save "Always use pnpm in this repo"', 'engram save --scope workspace rule "Keep this repo-local"', 'engram save --scope both knowledge "The app deploys through Vercel"', 'engram save --profile personal --scope global knowledge "My side project uses pnpm."', 'engram save rule --role frontend "Never hand-roll spacing; use design tokens"', 'engram save workflow --task-type release "When releasing, run tests, update changelog, tag version"', 'engram save rule --show-rule-variants "Always use pnpm in this repo"'], ['For long sessions with several candidates, use `engram save-session`; if you decline that suggestion, normal save captures the best single candidate.', 'Normal saves use the configured save target. Fresh installs default to `both`; `workspace`, `global`, and `both` are literal targets.', 'When task type is unclear and no `--task-type` is passed, Engram asks for a task type before saving. Use `--skip-task-type-prompt` to keep `task_type:unknown` in non-interactive flows.', 'Save previews may report related memories with suggested `depends_on` or duplicate cleanup; these are advisory and require human follow-up.', 'Rule previews show the balanced text; pass `--show-rule-variants` to see all three derived variants.', 'When `--profile` differs from the workspace default profile, Engram defaults the save to that profile global root so the workspace is not touched.', 'Every preview prints one `Verdict:` line after `File:`: `ADD`, `UPDATE <id>`, `SUPERSEDE <id>` (approving marks the old memory superseded), or `NOOP duplicate of <id>`. The verdict is deterministic (dedupe and related scores, no model call); `--force` never applies a SUPERSEDE.'], ['s', 'rule', 'skill', 'workflow', 'knowledge']),
  'save-session': topic('engram save-session', 'Propose multiple memories from a long session summary or agent brainstorm.', ['Mine a long human-agent interaction for several rules, knowledge facts, and workflows.', 'In AI agent chat, let the LLM define concise candidates from the current conversation before passing them to Engram.', 'Use `--query-level <n>` to ask an agent to include up to n recent human-agent chat sessions when it has access to them.', 'Read a transcript or summary from `--file transcript.md`.', 'Accept all candidates or only selected numbers such as `A 1,3`.', 'Use `--force` when the human explicitly wants Engram to attempt every agent-recommended candidate without a second reply.', 'With `--force`, ready candidates are saved and candidates needing related-memory review are deferred with ID-only `engram load --id` guidance; rerun deferred candidates only with `DEPENDS_ON` or `UPDATE`.', 'Add `--inbox` with `--force` to write a resumable receipt per deferred candidate under .agents/.engram/inbox/; then `engram review inspect <r-id>` and `engram review apply <r-id>`.', 'Use a `PARENT: <child-ids>` field on a candidate to declare that it generalizes existing children; the candidate writes cleanly without duplicate-flagging the intentional overlap, and its frontmatter stores `parent: [<id>]`.'], ['engram save-session', 'engram ss', 'engram save-session --query-level 3', 'engram ss -f last 50 sessions', 'engram save-session --file transcript.md', 'engram save-session --file transcript.md --force', 'engram save-session --file transcript.md --force --inbox', 'engram save-session --role frontend "TYPE: rule | TEXT: Always run tests before release."', 'engram save-session --show-rule-variants "TYPE: rule | TEXT: Always run tests before release."', 'engram ss --scope workspace', 'engram ss --scope both "TYPE: rule | TEXT: Always run tests before release."', 'engram ss -f --scope workspace "TYPE: rule | TEXT: Always run tests before release. | CONTEXT: Created from release planning so future agents preserve the release test gate."', 'engram ss -f --scope workspace "TYPE: rule | TEXT: OAuth rotation follows release foundations. | DEPENDS_ON: release-foundation | LEVEL: advanced"', 'engram ss -f --scope workspace "TYPE: knowledge | TEXT: Release foundation sets the gates every follow-up relies on. | PARENT: auth-rotation,deploy-gate"', 'engram ss -f --scope workspace "TYPE: knowledge | TEXT: Invoice retries use exponential backoff. | UPDATE: invoice-retry-baseline"'], ['Agents should provide one candidate per line using `TYPE: ... | TEXT: ...`.', 'Candidates may add optional `CONTEXT: ...` after `TEXT` when it helps explain why the memory exists, the source situation, intended use, or boundary.', 'Candidates may add `DEPENDS_ON: memory-id`, `LEVEL: advanced`, or `UPDATE: memory-id` fields after `TEXT`.', '`--query-level` must be a positive integer; agents should not invent unavailable chat history.', '`--force` is explicit approval for save-session only; do not add it unless the human requested it.', 'Rule previews show the balanced text; pass `--show-rule-variants` to see all three derived variants.', 'When `--force` defers candidates, ready candidates may already be saved; load listed IDs with `engram load --id ...` and rerun deferred candidates only with `DEPENDS_ON` or `UPDATE`.', 'If a related-memory hint displays match score `1.00`, tell the human the memory already exists, include the memory id, and rerun only with `UPDATE: memory-id` when the candidate extends it.', '`engram ss -f` is the compact shortcut for `engram save-session --force`; `engram ss -f last 50 sessions` normalizes to `engram save-session --query-level 50 --force`.', 'Save-session uses the configured save target unless `--scope workspace`, `--scope global`, or `--scope both` overrides it.', 'Each candidate preview prints a `Verdict:` line (`ADD`, `UPDATE <id>`, `SUPERSEDE <id>`, `NOOP duplicate of <id>`). `A` skips NOOP candidates and lists them as skipped; `A 1,3` writes exactly the numbered ones. `--force`, `take-control --force`, and autosave never apply a SUPERSEDE: it is deferred with `Action: rerun without --force to review SUPERSEDE <id>`.'], ['ss']),
  observe: topic('engram observe', 'Capture a sanitized raw note in the non-indexed inbox, then optionally mine it through save-session.', ['Store session notes without turning them into active memory yet.', 'Redact sensitive values and remove prompt-injection-like lines from raw notes.', 'Use `--propose` to immediately convert the sanitized note into approved memory proposals.', 'Use `--file` for transcripts or agentmemory exports you want to inspect first.', 'Drain the opt-in SessionEnd transcript queue with `--queue`; each queued transcript becomes a sanitized trace and inbox file, never a memory.'], ['engram observe "We fixed auth retries by refreshing tokens before expiry."', 'engram observe --file session.md', 'engram observe --file session.md --propose', 'engram observe --queue --dry-run', 'engram observe --queue --limit 10', 'engram observe --propose --force "TYPE: knowledge | TEXT: The auth middleware refreshes tokens before expiry."'], ['Inbox files live under `inbox/` and are not indexed as memories.', '`--propose` routes through save-session, so normal approval still applies unless the human explicitly passed `--force`.', '`--queue` reads the gitignored `session-queue.json` that `engram link claude|codex --session-end` fills. Each entry is checked (exists, regular file, not a link, at most 5 MiB), redacted, stripped of injection-like lines, and stored as a trace plus an inbox file; entries that were skipped or stored leave the queue, and entries that hit the inbox quota stay. `--dry-run` only inspects, `--limit n` caps entries per run. Run it yourself or from a plain command hook; do not run it from an async Codex hook.'], ['o']),
  'take-control': topic('engram take-control', 'Explore existing workspace guidance with agent help and consume it as Engram memory.', ['Convert AGENTS.md, CLAUDE.md, Cursor rules, memory-bank files, notes, and similar guidance into approved Engram memories.', 'Preview source selection with `--plan` before any LLM candidate step.', 'Scan top-level rules, skills, workflows, knowledge, notes, memory-bank, and project-memory folders, including .md and .txt files.', 'Use optional @the-long-ride/markdown-them to convert document files such as PDF, DOCX, HTML, RTF, and ODT into Markdown before extraction.', 'Use repeated `--file`, `--dir`, and `--include` flags to combine sources.', 'Use `--exclude`, `--max-sources`, `--max-chars`, and `--budget-tokens` (default 6000 for code/config scans; docs scans have no token budget unless asked) to keep scans token-safe.', 'Use `--kind code|config|all` (comma lists allowed; default `docs`) to digest code (shown as a per-directory repo map of symbol names and imports), config keys, and build manifests instead of only guidance docs; code scans default to `--max-sources 40`.', 'Use `--objective "<text>"` to name the current objective; the guidance then asks for both `OBJECTIVE: task` candidates useful for it and durable ones, and documents the optional `OBJECTIVE`, `SCOPE`, `APPLIES_TO`, and `DIRECTIVE` candidate fields.', 'Use `--refresh` after `engram verify --sources` to re-digest only the stale memories\' source files and propose exactly one `UPDATE: <id>` candidate per stale memory; approval is unchanged, and an applied update records the new source hashes and clears its `stale.json` entry.', 'Skip unchanged source hashes that were already imported, unless the human explicitly targets a file.', 'Use `--force` only when the human wants generated candidates saved without another A/B/C prompt; this mode uses token-light source defaults unless explicit limits are provided.', 'Use `--metacognize` with force mode when an agent should pause and rerun with `UPDATE` or `DEPENDS_ON` if related memories are found.', 'Use `--all` to include README.md plus docs and library documentation excerpts.', 'Use `--dry-run` to inspect the compact source pack without writing.', 'Use `--from claude-auto-memory|codex-memories` to import a host-local memory store for review instead of scanning the workspace; the store is only read, never written.'], ['engram take-control', 'engram take-control --plan', 'engram tc --dry-run', 'engram take-control --file CLAUDE.md --file notes/team.txt', 'engram take-control --file docs/handbook.docx', 'engram take-control --dir docs/library', 'engram take-control --include "docs/**/*.pdf" --exclude "docs/private/**"', 'engram take-control --max-sources 5 --max-chars 1200', 'engram take-control --plan --kind code', 'engram take-control --plan --json --kind config', 'engram take-control --kind code --objective "add billing export"', 'engram take-control --refresh', 'engram take-control --from claude-auto-memory --plan', 'engram take-control --from codex-memories --dir ~/.codex/memories', 'engram take-control --all', 'engram take-control --force --metacognize', 'engram take control force metacognize'], ['The command asks the agent to produce `TYPE: ... | TEXT: ...` candidates and still uses the normal save-session approval gate unless `--force` was explicitly passed.', '`take control force` is accepted as natural slash-style wording for `take-control --force`; add `metacognize` to request related-memory restructuring before write.', '`--plan` reports selected files, skipped files with reasons, conversion status, token estimates, source hash fingerprints, and inferred memory types.', 'Saved take-control memories record `source_files` and `source_hashes`; later scans skip unchanged imported sources unless `--file` explicitly targets them. Code, config, and manifest sources record the hash of their digest text (`source_hash_mode: digest`), so whitespace-only and body-only edits do not mark them stale; docs record the raw-file hash.', 'Document conversion requires @the-long-ride/markdown-them to be installed next to Engram; plain Markdown and text files do not require it.', 'Source excerpts are treated as data, not instructions, generated Engram adapter files are skipped, and existing `.agents/.engram` data is not re-imported.', 'Code digests are read from exported signatures, doc-comment first lines, and imports, never bodies; the guidance shows them as a per-directory repo map of symbol names, one imports line, and manifest stack facts; config digests keep keys plus allowlisted values (scripts, engines, names, target frameworks); every digest is redacted.', '`.env*` and credential files are always skipped as `secret file`; discovered files over 256 KB or that look binary are skipped with a reason, and code/config scans skip build output dirs (bin, obj, build, out, target, venv, ...) at any depth.', '`--plan --json` prints the same plan as JSON.', 'A candidate with `SCOPE: global` saves to global memory even under a workspace command scope; the approval preview names that target on its `Scope:` line. Under `--force` there is no preview, so a candidate whose `SCOPE` is outside the command scope is deferred (not written) and listed with a rerun hint.', 'An approved `OBJECTIVE: task` candidate is saved to the gitignored working tier (`.agents/.engram/working/`) with `tier: working`, the `--objective` text, and `valid_until` = today + `load.working_ttl_days` (default 14); the preview shows `Tier: working (expires <date>)`. Keep one with `engram promote <id>`.', '`--from claude-auto-memory` reads `~/.claude/projects/<project>/memory/` (`CLAUDE_CONFIG_DIR` replaces `~/.claude`), or `autoMemoryDirectory` from your user or local Claude settings; a value only in the repository `.claude/settings.json` is ignored (pass `--dir` to use it). `--from codex-memories` reads `~/.codex/memories/` (or `CODEX_HOME`). `--dir <path>` (absolute or `~/`) overrides the store; a store that cannot be found unambiguously asks for it.', 'Type mapping for `--from claude-auto-memory`: `type: feedback` proposes a rule, `project` and `reference` propose knowledge. `type: user` (personal profile data), untyped files, and the `MEMORY.md` index are skipped with a reason. `--from codex-memories` walks Markdown files up to two levels deep and lets the text decide the type.', 'Host imports never write into the host store. They are redacted and injection-filtered like any source and saved as `source: host-memory` with preset-relative `source_files` (for example `claude-auto-memory/feedback_testing.md`), raw `source_hashes`, and a `source_origin` hash of the store path, so no home path or user name reaches a memory file. `engram verify --sources` checks them only on the machine that holds the store (elsewhere they are skipped as `host memory store not on this machine`), and `--refresh` leaves them alone.', '`--from` cannot be combined with `--file`, `--include`, `--exclude`, `--kind`, `--all`, `--budget-tokens`, or `--refresh`. There is no Gemini preset: its inbox is already reviewed and the docs scan already covers GEMINI.md.'], ['tc']),
  metacognize: topic('engram metacognize', 'Let an agent restructure an existing Engram memory folder through approved save-session candidates.', ['Review workspace memory for duplicates, over-broad memories, missing dependencies, and wording cleanup.', 'Review global memory without touching workspace memory.', 'Review both scopes together when the human asks for all memory to be reorganized.', 'Use `--dry-run` to show the compact memory source pack before generating candidates.', 'Use `--force` only when the human explicitly wants every generated restructure candidate saved.'], ['engram metacognize --workspace', 'engram metacognize --global --dry-run', 'engram metacognize --all --force', 'engram mc --workspace -f "TYPE: knowledge | TEXT: OAuth memory is consolidated. | UPDATE: oauth-memory"', 'engram restructure workspace memory force'], ['The command reads active `rules/`, `skills/`, and `knowledge/` memories from the selected scope, verifies hashes, and gives the agent a compact source pack.', 'Agents return `TYPE: ... | TEXT: ...` candidate lines, usually with `UPDATE: existing-id` for restructuring and `DEPENDS_ON: memory-id` for layered memory.', 'Without `--force`, Engram shows the normal numbered approval gate before writing.', 'With `--force`, related-memory hints still pause before writing so the agent can rerun with better `UPDATE` or `DEPENDS_ON` structure.', 'This command does not delete or archive memories; use `engram archive --reason <why> <id|file>` separately after review.', 'Natural wording such as `restructure global memory force` normalizes to this command.'], ['mc']),
  load: topic('engram load', 'Route and print memories relevant to the current task.', ['Start an agent session with relevant project memory.', 'Load only the context needed for a specific task.', 'Refine broad matches down to the configured compact context pack.', 'Use `engram route "<task>"` to preview the classifier label before loading.', 'Use `--profile <name>` to load from a specific profile global root.', 'Use `--all` when you intentionally want broad context.', 'Set `--budget-tokens <200-16000>` when the compact output needs a per-call cap.', 'Default load now uses the compact agent-facing output.', 'Use `--disclosure full` to print every packed body instead of the tiered pack.', 'Pass `--exclude-keys <scope:file,...>` to skip memories the caller already holds.', 'Use `--id <id>[,<id>]` to fetch specific memories, such as the ids in a `fetch:` hint; an explicit fetch skips routing and the token budget and counts as a local `fetched` usage.', 'Use `-f` or `--full` when you intentionally want the broader legacy output.', 'Use `--dry-run` to preview routed files, candidate counts, and narrowing tags without printing memory contents.', 'Use `--explain` to inspect ranking signals, sources, omissions, and zero-result diagnosis without loading memory bodies.'], ['engram load "deployment workflow"', 'engram load --budget-tokens 800 "deployment workflow"', 'engram load --disclosure full "deployment workflow"', 'engram load --exclude-keys workspace:rules/use-pnpm.md "install deps"', 'engram load --id use-pnpm,deploy-gate', 'engram ld -f "deployment workflow"', 'engram route "deployment workflow"', 'engram --profile company load "deployment workflow"', 'engram load --dry-run "auth hardening"', 'engram load --explain "auth hardening"', 'engram load --all', 'engram load --full "auth hardening"'], ['Low-confidence memories are skipped unless explicitly loaded through manual paths.', 'When more candidates match than the load limit allows, Engram anchors on meaningful query terms, then reranks with tags, recency, graph, and vector signals before loading the compact pack.', '`workflow` and `workflows` are treated as skill-routing aliases without making generic memory type words broad matches.', 'Normal load prints the expanded count and total related count, such as `loaded 3 memory files / 14 total related memories`.', 'Default `auto` disclosure expands the top `load.expand_top` (default 3) hits as bodies, lists the other selected hits plus up to 5 omitted candidates as one-line cards under `related:`, and ends with `fetch: engram load --id <ids>`.', 'Dependencies of expanded hits are expanded into the `load.dependency_reserve_ratio` share of the budget when they fit; a hit too large for the budget becomes a card rather than being dropped, and only when the cards alone exceed the cap are the lowest-ranked ones left out.', 'Set `load.disclosure` to `full` in config to keep the untiered output; `--all`, `--full`, and `--id` always bypass tiering.', '`--exclude-keys` rows get no body or card; `--json` reports them under `already_loaded`.', 'If `--profile` differs from a workspace default profile, workspace memory is disabled for that command.', '`--dry-run` reports file paths, types, summaries, total related memories, and suggested tags for narrowing broad queries.', '`--budget-tokens` caps the complete compact output, including summary and safe diagnostics; `--all`, `--full`, and explicit `--id` bypass this cap.', '`--all` returns every visible routed memory instead of applying the configured cap.', 'Default compact load prints no frontmatter: each expanded hit is a `### <id> [<type>, <authority>]` heading followed by its directive or Content bullets (rules render one selected rule variant), and the other hits are one-line `related:` cards.', '`-f` is the short alias for `--full` on `load` only.', '`--full` restores the broader legacy load output.', 'Use `engram set-load-limit` to tune the compact cap from 1 to 32; default is 8.', 'When a scope reaches the vector threshold, Engram can use an optional sqlite-vec sidecar for candidate expansion while keeping lexical and graph fallback active.', 'Agent hooks may plan below `load.max_tokens` on Codex (2,400 tokens) and Claude (9,500 characters) so the whole hook payload stays under the host cap; bodies demote to cards instead of being cut. Hook proof `sig` hashes the sorted routed keys.'], ['ld']),
  route: topic('engram route', 'Classify a task into the stable task type used by load and save tags.', ['Preview which task type a user request maps to before running `engram load`.', 'Confirm the `task_type:*` tag a save will receive.', 'Use in agent startup flows before the first action.', 'Debug deterministic classifier behavior without reading memory contents.'], ['engram route "fix the CLI parser bug"', 'engram route "plan the release workflow"', 'engram route "explain the memory schema"'], ['The classifier accepts explicit labels like `task_type:debugging` and returns `Task type`, `Confidence`, `Load query`, and `Save tags`.', 'If classification is unclear, `engram route` returns `task_type:unknown` with confidence `0.00`.', 'Save paths ask for a task type when classification is unclear unless `--skip-task-type-prompt` is passed.'], ['rt']),
  search: topic('engram search', 'Search visible indexed memories.', ['Find whether a fact or rule already exists.', 'Locate duplicate or stale memory before saving.', 'Audit topic coverage.', 'Use local semantic scoring for related terms such as package manager and pnpm.'], ['engram search "pnpm"', 'engram search --semantic "package manager"', 'engram f "deployment"'], ['Default search is deterministic lexical search.', '`--semantic` uses deterministic local similarity over normalized terms, concept aliases, and tags; it does not require embeddings.', 'Search uses the visible index, so ignored memories stay hidden.'], ['f']),
  graph: topic('engram graph', 'Inspect the derived layered JSON memory graph.', ['See memory as scope, type, topic, and memory nodes instead of one flat list.', 'Debug graph-aware routing for a query.', 'Review explicit `depends_on: [...]` prerequisite layers from foundation to deeper memories.', 'Find contradiction candidates that may indicate wrong or stale memory.', 'Regenerate `memory.graph.json` with `--rebuild`.'], ['engram graph', 'engram graph "deployment"', 'engram graph --rebuild "pnpm"'], ['The graph is derived from approved Markdown memories and can be rebuilt at any time.', 'Memories can declare `depends_on: [base-memory-id]` in frontmatter; load keeps prerequisites in the compact route before dependent memories.', 'Contradiction candidates are advisory; archive wrong memory only after review.'], ['g']),
  verify: topic('engram verify', 'Verify memory hashes for workspace and global scopes.', ['Detect hand-edited or tampered memory files.', 'Run before committing memory changes.', 'Check only one scope when debugging.', 'Use `--sources` to re-hash the source files of take-control memories against their `source_hashes` and record changed or missing ones in the local `.agents/.engram/stale.json`.'], ['engram verify', 'engram verify workspace', 'engram vf global', 'engram verify --sources', 'engram verify --sources --json'], ['Hash mismatches make `load` skip unsafe content.', 'Stale sources never fail `verify`; `load` ranks stale memories lower and ends their cards with ` (stale)`, and `engram take-control --refresh` proposes updates for them.', '`stale.json` is gitignored derived state, rewritten only when its content changes and removed when nothing is stale. Source paths must stay inside the workspace: absolute paths, `..`, links (symlinks and hard links), secret files, `.git`, and Engram data are reported unchecked, never read. Raw (docs) hashes ignore line-ending and BOM changes. A global take-control memory records a `source_origin` fingerprint (sha256 of its workspace root path) and is checked and refreshed only in that workspace; older global memories without one are skipped.'], ['vf']),
  rehash: topic('engram rehash', 'Recompute and store hashes for all memory files.', ['Fix hash mismatches after hand-editing or linter changes.', 'Refresh hashes when content was modified outside Engram.', 'Check only one scope when debugging.'], ['engram rehash', 'engram rehash workspace', 'engram rh global', 'rehash memory', 'refresh hashes'], ['Rehash reads every `.md` file under `rules/`, `skills/`, and `knowledge/` and writes the full hash store.', 'Use after `engram verify` reports mismatches or after manual file edits.', 'Natural phrases like `rehash memory` or `refresh hashes` normalize to `engram rehash`.'], ['rh']),
  'rebuild-index': topic('engram rebuild-index', 'Rebuild memory indexes from Markdown files.', ['Recover after index files were deleted.', 'Refresh indexes after approved manual cleanup.', 'Debug missing search/load results.', 'Refresh eligible sqlite-vec sidecars after schema changes.'], ['engram rebuild-index', 'engram rebuild-index workspace', 'engram ri global'], ['Invalid memory files are skipped during rebuild.', 'Vector sidecars are skipped when the scope is below threshold or sqlite-vec is unavailable.', 'Also refreshes native path rules for linked Claude/Cursor.'], ['ri']),
  repair: topic('engram repair', 'Report invalid memory files that rebuild-index would skip.', ['Find malformed Markdown memories that are missing from search/load.', 'Check memory health after manual file edits or imports.', 'Review exact schema errors before fixing a file.'], ['engram repair', 'engram repair workspace', 'engram rp global', 'engram repair --move-backups', 'engram repair workspace --move-backups --confirm'], ['Without flags, repair only reports; fix or archive the reported file, then run `engram rebuild-index`.', '`--move-backups` plans moving `*.bak` files from rules/skills/knowledge into `backups/<kind>-<label>/`; add `--confirm` to move them.'], ['rp']),
  doctor: topic('engram doctor', 'Run composed diagnostics for config, roots, hashes, invalid files, index, graph, policy, and host linkage.', ['Diagnose a broken workspace after manual edits or upgrades.', 'Verify hashes and detect invalid memory files in one pass.', 'Check host executable detection, Engram skillset linkage, and local policy validity.', 'Use --strict for CI: non-zero exit on any warning or failure.'], ['engram doctor', 'engram doctor --json', 'engram doctor workspace --strict', 'engram doctor --scope global'], ['Doctor checks config resolution, root existence, hash integrity, invalid files, index/graph status, policy validity, host executables, and Engram skillset linkage.', 'The `host.skill_frontmatter` check validates every Engram-generated SKILL.md against the Agent Skills spec (plus Claude Code fields for Claude skills) and warns per invalid field; skills Engram did not write are ignored.', 'The `host.agents_md_chain` check sums the Codex AGENTS.md chain and warns at 80% of `project_doc_max_bytes` (32 KiB by default).', 'Vector freshness and MCP/hook installation checks arrive in later milestones.', '--strict turns warnings into non-zero exit for CI use.', '--json emits a versioned contract envelope.']),
  policy: topic('engram policy', 'Inspect, validate, audit, or roll back policy-controlled autonomous writes.', ['Use `init` to create deny-by-default policy.', 'Use `validate --strict` in CI; missing or invalid policy then fails.', 'Use `show` and `audit` to inspect policy state without exposing memory content.', 'Use `rollback <audit-id>` for the immediate archive-based rollback path.'], ['engram policy init', 'engram policy validate --strict --json', 'engram policy audit --json', 'engram policy rollback <audit-id>'], ['Policy lives at `.agents/engram.policy.json`.', 'Missing or invalid policy denies autonomous writes.', 'Audit output contains hashes, IDs, scopes, and paths only; candidate bodies are never returned.']),
  autosave: topic('engram autosave', 'Evaluate one candidate through explicit local policy.', ['Pass `--policy` to make the policy gate explicit.', 'Use `--dry-run` to inspect a permitted decision without writing.', 'Autonomous writes remain denied until policy enables mode `autonomous`.'], ['engram autosave --policy --dry-run --json "TYPE: knowledge | TEXT: ..."'], ['Autosave never writes with missing or invalid policy.', 'Allowed writes remain limited by policy type, scope, and source allowlists.', 'A candidate `SCOPE:` picks the target when `--scope` is omitted; a `SCOPE:` that differs from `--scope` is denied. `DIRECTIVE:` and `APPLIES_TO:` are written as in save-session.']),
  capabilities: topic('engram capabilities', 'Show declared host adapter capabilities.', ['Inspect which hosts support instructions, skillsets, MCP, injection, proof, transcript events, and cleanup.', 'Use host-specific output when an adapter cannot provide a capability.'], ['engram capabilities --json', 'engram capabilities cursor --json'], ['Unsupported capabilities are reported explicitly rather than inferred.']),
  audit: topic('engram audit', 'List visible memories with optional author, stale, and confidence filters.', ['Find old memories that may need review.', 'Show memories owned by a teammate.', 'Inspect low-confidence candidates.'], ['engram audit', 'engram audit --stale', 'engram audit --author dev@example.com', 'engram a --low-confidence'], ['Audit reports metadata rows, not full memory content.'], ['a']),
  health: topic('engram health', 'Summarize memory health metrics.', ['Check memory coverage and quality trends.', 'Spot unhealthy memory stores before sharing.', 'Prepare for team review.'], ['engram health', 'engram he'], ['Use with `quality-check` for deeper quality signals.'], ['he']),
  'quality-check': topic('engram quality-check', 'Evaluate visible memory quality and potential issues.', ['Find vague or low-value memories.', 'Improve memory before exporting to agents.', 'Review memory hygiene during maintenance.'], ['engram quality-check', 'engram qc'], ['Quality checks are advisory; they do not write files.'], ['qc']),
  stats: topic('engram stats', 'Show counts, scope mix, and author ownership for visible memories.', ['Confirm a save increased memory count.', 'Compare workspace and global memory volume.', 'See team memory ownership by author.', 'Check whether ignore rules are hiding entries.', 'Use `--usage` to see which memories agents actually fetch and which were injected but never fetched for 30 days.'], ['engram stats', 'engram stats --usage', 'engram st'], ['Stats respect visibility filters and include the former team-dashboard ownership summary.', '`--usage` reads the local, gitignored .agents/.engram/usage.json; only explicit `load --id` and MCP `resources/read` of a memory count as a fetch.'], ['st']),
  deduplicate: topic('engram deduplicate', 'Detect similar or duplicate visible memories.', ['Find repeated rules before they confuse agents.', 'Clean up after imports or team merges.', 'Prepare memory for a release.'], ['engram deduplicate', 'engram deduplicate --semantic', 'engram dd'], ['Default matching uses strict token overlap.', '`--semantic` uses deterministic local similarity over normalized terms and tags; it does not require embeddings.'], ['dd']),
  export: topic('engram export', 'Export visible memory to agent instruction formats or a JSON bundle.', ['Generate AGENTS.md, CLAUDE.md, or Cursor rules.', 'Share a reviewable bundle.', 'Feed memory into an agent without runtime integration.'], ['engram export --format agents-md', 'engram export --format claude-md', 'engram x --format cursor-rules', 'engram export', 'engram export --out bundle.json'], ['Exports skip ignored or unsafe memory.', '`cursorrules` is a deprecated alias for one release and prints a note on stderr. `cursor-rules` writes `.mdc` frontmatter with `description` and `alwaysApply: false`.', 'Without `--format` or `--out`, the JSON bundle is written to the gitignored `.agents/.engram/exports/engram-bundle-<date>.json`; it keeps live working (task-scoped) memories. Without a workspace Engram folder it is written to the current directory and leaves working memories out.', 'With an explicit `--out`, the bundle keeps live working memories and the command prints how many it contains.'], ['x']),
  import: topic('engram import', 'Import an Engram or agentmemory JSON bundle through the approval gate.', ['Review memory from another workspace.', 'Move memory between machines.', 'Merge team memory with human oversight.', 'Convert agentmemory export JSON into proposed Engram Markdown memories.'], ['engram import bundle.json', 'engram import --source agentmemory agentmemory-export.json', 'engram import --max 10 agentmemory-export.json', 'engram im team-memory.json'], ['Imports should never bypass approval.', 'agentmemory imports auto-detect memories, semantic memories, procedural memories, lessons, and insights when present.'], ['im']),
  promote: topic('engram promote', 'Move a working-tier memory to durable memory after A/B/C approval.', ['Keep a task-scoped `OBJECTIVE: task` memory after the objective is done.', 'Review the promoted Markdown before it becomes durable; `A` promotes, `B <note>` promotes with a human note, `C` leaves it in the working tier.', 'Target one scope with `workspace:<id>` or `global:<id>` when both scopes hold the same working id.'], ['engram promote billing-export-uses-csv', 'engram promote workspace:billing-export-uses-csv'], ['Approved `OBJECTIVE: task` candidates are written to `.agents/.engram/working/<type-dir>/<id>.md` with `tier: working`, the command `--objective` text as `objective` when given, and `valid_until` = today + `load.working_ttl_days` (default 14).', 'Promote moves the file to `<type-dir>/`, drops `tier` and `valid_until`, keeps `objective` as provenance, bumps `revision`, and rehashes and reindexes through the normal approved-write path (safety scans, schema validation, global Git commit for global memory).', 'Expired working memories cannot be promoted; save them again or prune them with `engram working prune`.', 'Unknown ids and memories that are already durable report a clear error and write nothing.']),
  working: topic('engram working', 'Maintain the working memory tier (task-scoped, gitignored, expiring memories).', ['Delete working memories whose `valid_until` has passed with `engram working prune`.', 'Preview what would be deleted with `--dry-run`.', 'Jot a task note with `engram working note "<text>"`; add `--objective "<text>"` to tie it to a session objective, `--type knowledge|rule` (default knowledge), and `--scope workspace|global` (default workspace).'], ['engram working prune --dry-run', 'engram working prune', 'engram working note "The ledger worker retries invoices twice" --objective "add billing export"'], ['`working note` redacts the text and refuses instruction-like lines, shows the working-tier file it would write, and asks one `Y` / `C` prompt: only `Y` or `yes` writes; `C` or anything else writes nothing. The MCP tool `engram_note` asks the same question (a host dialog when supported, otherwise an approval token for `engram_commit`).', 'A note is saved with `source: note`, `tier: working`, the `--objective` text, and `valid_until` = today + `load.working_ttl_days`. It never matches or updates a durable memory; `engram promote <id>` is the only way to make it durable.', 'SessionStart leaves notes out unless the session objective (the `ENGRAM_SESSION_OBJECTIVE` environment variable) matches the note objective; in other loads a non-matching note appears only as a one-line card.', 'Working memories live under `.agents/.engram/working/` (and `<global>/working/`), which the scope `.gitignore` excludes, so they never reach Git.', 'They load, search, and route like durable memory until `valid_until` passes; expired ones are left out of `load` with reason `lifecycle`, and agent output marks them `working`.', 'Prune only deletes regular `.md` files under `working/` whose `valid_until` is before today; symlinks are not followed and durable memory is never touched. Indexes, graphs, and hashes are rebuilt afterwards.', 'Their index, graph, and hash entries live in local sidecars under `working/`, and their writes skip the changelog and global Git, so the committed sidecars never name a working memory; after upgrading from an older build run `engram rebuild-index` if doctor reports stale working entries.', 'Prune reports working memories with no `valid_until` (they never expire) without deleting them; doctor warns about them too.', 'Set the TTL as `load.working_ttl_days` (integer from 1 to 365, default 14) in the Entry Construct tab or the `load` block of `engram.config.json`; `engram config set` does not accept this key.']),
  archive: topic('engram archive', 'Move wrong or superseded memory out of active routing after approval.', ['Remove stale or wrong memory from `load` without deleting its history.', 'Let an AI agent propose cleanup while the human keeps the final approval gate.', 'Preserve archived Markdown under `archive/YYYY-MM-DD/`.'], ['engram archive use-pnpm-for-installs --reason "Repo migrated to npm."', 'engram archive workspace:rules/use-pnpm-for-installs.md', 'engram ar knowledge/old-deploy-fact.md'], ['Archive is a move, not a hard delete.', 'Archiving a workspace memory also archives its matching global copy when one exists.', 'Run `engram graph` or `engram quality-check` first to find likely contradiction candidates.'], ['ar']),
  review: topic('engram review', 'Review derived memory findings and apply deferred-save inbox receipts.', ['Check for duplicate or contradictory memories without reading bodies.', 'Find memories past their review_after date or older than 180 days.', 'Catch depends_on references to missing memory ids.', 'Dismiss false positives; findings persist by fingerprint across rebuilds.', 'Verify, supersede, or archive linked memories.', 'List pending deferred-save receipts with `inbox` and inspect or apply a single receipt by id (r-xxxxx).', 'Use `review apply <receipt-id> --depends-on <id>` or `--update <id>` to resolve relation choices using IDs only.', 'Apply runs the candidate through the normal save approval flow — no bypass unless the human explicitly passes `--force`.'], ['engram review list', 'engram review list --kind duplicate --json', 'engram review inbox', 'engram review inspect duplicate:memory-a,memory-b', 'engram review inspect r-abcd1234', 'engram review apply r-abcd1234 --depends-on memory-id', 'engram review apply r-abcd1234 --update memory-id', 'engram review cleanup', 'engram review dismiss stale:old-memory --note "reviewed"', 'engram review verify old-memory', 'engram review supersede old-memory new-memory', 'engram review archive wrong-memory --reason "superseded"'], ['Review never exposes memory bodies or authors — only ids, kinds, and summaries.', 'Findings are rebuilt from the index and graph; dismissals persist by fingerprint so a rebuild never resurrects a dismissed finding.', 'Inbox receipts are opt-in via `engram save-session --inbox`; files live under .agents/.engram/inbox/<id>.json and contain no related-memory bodies — only ids and the deferred candidate text.', 'Expired receipts are removed opportunistically by `inbox`, `inspect`, `apply`, and `cleanup`; deletion never affects approved memory.', '--json emits a versioned contract envelope.', 'The review queue may be empty on a healthy memory store.']),
  benchmark: topic('engram benchmark', 'Run versioned retrieval regression metrics for a safe JSON case file.', ['Compare routing changes before and after graph tuning.', 'Assert expected, forbidden, dependency, scope, and zero-result behavior.', 'Use `--baseline`, `--policy`, and `--fail-on regression` for CI gates.', 'Use `--write-report` to persist a body-free report.'], ['engram benchmark eval/cases.json --json', 'engram benchmark cases.json --policy --baseline baseline.json --fail-on forbidden,recall', 'engram bm memory-cases.json'], ['Case files support `version`, `id`, `query`, `expect`, `forbid`, `depends_on`, `scope`, `limit`, `max_tokens`, `category`, and `expect_omitted`.', '`path-trigger` cases treat `query` as a file path and run through the PreToolUse path trigger; `working-expired` cases expect `lifecycle` omissions; both report in separate blocks. `hook_tokens_mean` simulates SessionStart plus 3 prompt turns.', 'Legacy arrays and `{cases:[...]}` files remain accepted.', 'Reports contain IDs and metrics only; memory bodies are never emitted.'], ['bm']),
  ignore: topic('engram ignore', 'Manage ignore rules for memory visibility.', ['Hide private or noisy memory from routing.', 'Check whether a path is ignored.', 'Add project-specific ignore patterns.'], ['engram ignore status', 'engram ignore check knowledge/private.md', 'engram ignore add private/**', 'engram ig status'], ['Ignore rules affect search, load, export, and stats.'], ['ig']),
  'set-role': topic('engram set-role', 'Configure active developer roles for context routing.', ['Load frontend-only memory during UI work.', 'Load backend and security memory during auth work.', 'Clear roles when you want unfiltered routing.'], ['engram set-role frontend design', 'engram set-role backend security', 'engram set-role docs', 'engram set-role'], ['When roles are set, memories with non-matching `role: [...]` frontmatter are skipped. With no active roles, role filtering is disabled.', 'Successful updates return an `Agent action:` line so Engram-aware adapters can reload the current task/request immediately and replace prior Engram-loaded context in the same conversation.'], ['sr', 'role', 'roles', 'set-roles']),
  'set-save-target': topic('engram set-save-target', 'Configure where normal save writes by default.', ['Keep memory local to the current repository with workspace.', 'Save only portable personal or team memory with global.', 'Write approved memories to both workspace and global at the same time.', 'Inspect the current target with status.'], ['engram set-save-target status', 'engram set-save-target workspace', 'engram set-save-target global', 'engram set-save-target both'], ['Fresh installs default to `both`.', '`global` requires configured global memory. `both` writes workspace and global when global memory is configured, and otherwise falls back to workspace until a global path exists.', 'Per-command `--scope workspace|global|both` overrides this default for save, save-session, take-control, observe propose, and agentmemory import.'], ['save-target']),
  'set-load-limit': topic('engram set-load-limit', 'Configure the compact load cap.', ['Keep normal agent startup compact in small or noisy memory stores.', 'Raise the cap when a workspace has many tightly related foundational memories.', 'Lower the cap when you want stricter token control.', 'Inspect the current limit with status.'], ['engram set-load-limit status', 'engram set-load-limit 12', 'engram ll 6', 'engram set-load-limit reset'], ['The value must be an integer from 1 to 32.', 'Default is 8.', '`engram load --all` remains the explicit way to bypass the cap for broad context.', 'Normal load reports both the selected count and total related memories so agents can decide whether to narrow or restructure memory.'], ['ll', 'load-limit']),
  'set-proof': topic('engram set-proof', 'Configure whether supported hooks append compact Engram proof lines to eligible responses.', ['Keep proof off when only hidden context injection is desired.', 'Use compact proof when agents should show whether Engram loaded, reused, or skipped memory on each eligible turn.', 'Inspect the current proof mode with status.'], ['engram set-proof status', 'engram set-proof compact', 'engram set-proof off', 'engram sp compact'], ['Proof visibility is separate from `set-read`; it does not change when full Engram memory is injected.', 'With `compact`, supported hooks can append a short `Engram proof:` line even when read mode skips loading on that turn.'], ['sp', 'proof']),
  'set-read': topic('engram set-read', 'Configure how and when engram load is used.', ['Choose startup to inject memory only when a supported host starts or resumes a session.', 'Choose auto (default) to inject at session start and then only memory bodies not yet delivered in the session.', 'Choose always to re-inject every routed body on every eligible prompt, even when it was already delivered.', 'Choose manual to disable automatic hooks while keeping manual `engram load` available.', 'Choose off to suppress automatic hook injection and keep read surfaces quiet.', 'Check active read behavior with status.'], ['engram set-read status', 'engram set-read startup', 'engram set-read auto', 'engram set-read always', 'engram set-read manual', 'engram set-read off', 'engram rd status'], ['Hook-aware hosts use `startup`, `auto`, `always`, `manual`, and `off` directly.', 'The local, gitignored hook cache (`agent-hook-cache.json`) stores per host, hashed cwd, and session id only the delivered memory keys and a timestamp; raw prompt text is never stored. A new session or a compaction (`PreCompact`, Gemini `PreCompress`) resets the delivered set. A repo with no `.agents/.engram` folder (global memory only) keeps no cache, so `auto` re-injects there on every eligible prompt.', 'If you change this setting, installed hooks pick it up on their next run.', 'Changing it also refreshes native Claude/Cursor path rules: `off`, `manual`, and `startup` remove the generated rule files, `auto` and `always` restore them.'], ['rd', 'read']),
  'set-rule-variant': topic('engram set-rule-variant', 'Tune how strict rule memories render for agents.', ['Use strict for lower-tier models that need stronger guardrails.', 'Use light or balanced for top-tier models so rules do not limit their reasoning power.', 'Turn variants off when compact output is preferred.'], ['engram set-rule-variant strict', 'engram set-rule-variant balanced', 'engram set-rule-variant off', 'engram rv status'], ['Engram derives light and strict rule wording from the saved Content at render time; custom wording supplied with LIGHT/BALANCED/STRICT is kept in the file. This command only changes the rendered output for load/export/sync.', 'When variants are off, Engram renders balanced rule wording by default.', 'Successful updates return an `Agent action:` line so Engram-aware adapters can reload the current task/request immediately and replace prior Engram-loaded context in the same conversation.'], ['rv', 'rule-variant']),
  'resolve-conflicts': topic('engram resolve-conflicts', 'Preview or resolve Engram-owned Git conflicts in memory files.', ['Inspect memory merge conflicts safely.', 'Resolve deterministic Engram-owned conflicts.', 'Avoid touching unrelated project files.', 'Append a workspace metacognize source pack when an agent should restructure memories after conflict review.'], ['engram resolve-conflicts --dry-run', 'engram resolve-conflicts', 'engram resolve-conflicts --dry-run --metacognize', 'engram resolve conflicts and metacognize', 'engram rc --dry-run'], ['Use `--dry-run` first when reviewing team memory conflicts.', '`--metacognize` runs the workspace metacognition flow after the conflict preview or resolution, so agents can produce `UPDATE` or `DEPENDS_ON` candidates.'], ['rc']),
  'install-hooks': topic('engram install-hooks', 'Install Git hooks for local Engram integrity checks.', ['Verify workspace memory before commits.', 'Resolve Engram memory conflicts after pulls.', 'Add guardrails to team workflows.'], ['engram install-hooks', 'engram ih'], ['Human-authored hooks are preserved unless generated by Engram.'], ['ih']),
  'agent-hook': topic('engram agent-hook', 'Internal JSON hook runtime used by installed agent hooks.', ['Run from Codex, Claude, Gemini, Cursor, Windsurf, or OpenCode hook JSON.', 'Read hook payload JSON from stdin and emit host-compatible JSON on stdout.', 'Fail open with `{}` when input or loading fails.'], ['engram agent-hook --host codex', 'engram agent-hook --host claude', 'engram agent-hook --host gemini', 'engram agent-hook --host cursor', 'engram agent-hook --host windsurf', 'engram agent-hook --host opencode'], ['This command is meant for hook adapters, not normal interactive use.', 'It never stores raw prompt text; the cache stores only the delivered memory keys per host, hashed cwd, and session id.', 'The OpenCode host emits retain/replace/clear directives so the plugin can manage in-process context.', 'Cursor hooks inject context through `additional_context` on sessionStart; beforeSubmitPrompt is not used for context injection.', 'Windsurf hooks run pre_user_prompt for audit/preload; they cannot inject model context directly.']),
  link: topic('engram link', 'Link Engram skillset, MCP config, slash adapters, and agent hooks to an AI agent.', ['Link AGENTS.md instructions for Codex-compatible agents.', 'Link Gemini context files, including the current Gemini-compatible Antigravity surfaces.', 'Link Cursor with workspace rules, MCP, and sessionStart hook.', 'Link Windsurf with workspace rules and hook; MCP is global-only.', 'Link OpenCode with a generated plugin that routes prompts and injects memory.', 'Link slash command adapters.', 'Claude and Codex hooks also register `SubagentStart`, so subagents get routed memory.', 'Gemini gets an AfterTool path trigger for read_file|write_file|replace.', 'Opt in to a Claude or Codex SessionEnd hook with `--session-end`; it only queues the transcript path for `engram observe --queue`.', 'Configure MCP-capable clients.', 'Link global user rules, MCP, or skills so an AI agent loads Engram global memory in new workspaces.', 'Bulk-link memory children to a parent by adding DEPENDS_ON refs across visible workspace and global memories.'], ['engram link all', 'engram link claude --session-end', 'engram link codex', 'engram link cursor', 'engram link windsurf', 'engram link gemini', 'engram link opencode', 'engram link slash', 'engram link --global codex', 'engram link --global cursor', 'engram link --global windsurf', 'engram link --global copilot', 'engram link --global claude', 'engram link --global gemini', 'engram link --global opencode', 'engram link --global all', 'engram lk list', 'engram link --parent release-foundation --children auth-rotation --children deploy-gate'], ['Existing human-authored files are skipped unless `--force` is used.', '`--session-end` is off by default and `upgrade` never adds it. It registers a plain SessionEnd command hook (Claude timeout 5 s, Codex 3 s) that appends the transcript path, host, and session to the gitignored `session-queue.json` (at most 50 entries) and injects nothing; Gemini is not registered. Stored paths are absolute and name your OS user, which is why the file never leaves your machine. Drain it with `engram observe --queue`.', '`link claude` writes the AGENTS.md block, and refreshes a CLAUDE.md block only when CLAUDE.md exists.',
    'With `hooks.path_rules` native (default), `link claude` writes `.claude/rules/engram/<id>.md` and `link cursor` writes `.cursor/rules/engram/<id>.mdc` for workspace memories with `applies_to`; Claude registers `InstructionsLoaded` instead of `PreToolUse`. Working-tier memories are never written, and global memories go to `~/.claude/rules/engram/` on `link --global claude`. `engram config set hooks.path_rules hook` keeps the Claude `PreToolUse` hook and removes the Claude rule files.', '`agents-md` is the generic AGENTS.md fallback for unlisted AGENTS.md-compatible agents.', '`gemini` also covers current Antigravity 2.0, Antigravity CLI, and Antigravity IDE Gemini-compatible paths while Google keeps those surfaces in flux.', 'Workspace Cursor writes `.cursor/rules/engram.mdc`, `.cursor/engram.md`, `.cursor/mcp.json`, and a `sessionStart` hook.', 'Global Cursor installs a local plugin at `~/.cursor/plugins/local/engram` with rules, skills, commands, MCP, and hooks.', '`cascade` is accepted as a compatibility alias for `windsurf`.', 'Workspace Windsurf writes `.windsurf/rules/engram.md`, `.windsurf/engram.md`, and a `pre_user_prompt` hook.', 'Windsurf workspace does not generate MCP; run `engram link --global windsurf` for MCP.', 'Global Windsurf writes `~/.codeium/windsurf/memories/global_rules.md`, `mcp_config.json`, and `hooks.json`.', 'Cursor hooks inject context through `additional_context` on sessionStart; beforeSubmitPrompt is not used for context injection.', 'Windsurf hooks can audit/preload/block, but cannot inject model context; rules and MCP provide AI-visible context.', 'Global installs append one Engram managed block at the end of shared instruction files and record successful installs for future `engram upgrade` refreshes.', 'Global Copilot writes `~/.copilot/copilot-instructions.md`.', 'Hookless Claude installs (no Engram Claude hooks) launch `engram-mcp --always-load`, which marks `engram_load` with `anthropic/alwaysLoad` so Claude Code loads it upfront.', '`engram-mcp --no-elicitation` keeps the chat approval_token flow for hosts whose elicitation dialog is unreliable.', 'Global Claude writes `~/.claude/CLAUDE.md` and `~/.claude/skills/engram/SKILL.md`; global MCP for Claude is a printed `claude mcp add --scope user engram -- engram-mcp` hint because Claude Code does not read `~/.claude/mcp.json`.', 'Gemini MCP is merged into `.gemini/settings.json` (workspace) or `~/.gemini/settings.json` (global); global Codex writes a managed `[mcp_servers.engram]` block in `~/.codex/config.toml`.', 'Global OpenCode writes `~/.config/opencode/plugins/engram.js` and `~/.config/opencode/opencode.jsonc` by default.', 'MCP configuration is included automatically for Cursor and all link targets.']),
  unlink: topic('engram unlink', 'Remove Engram skillset, MCP config, instruction content, and agent hooks from an AI agent.', ['Remove generated skillset files from a workspace.', 'Remove global agent skillset, MCP, and managed blocks.', 'Clean up Engram integration from an AI agent.'], ['engram unlink all', 'engram unlink codex', 'engram unlink --global claude', 'engram unlink --global opencode', 'engram unlink --global all'], ['Removes generated files; human-authored files are skipped unless `--force` is used.', 'Global managed blocks (instruction wrappers) are cleaned from shared files.', 'For OpenCode, the generated `plugins/engram.js` is removed; a human-authored plugin is preserved unless `--force` is used.', 'Registry entries are cleaned after unlink.', 'Engram-generated native rule files (`.claude/rules/engram`, `.cursor/rules/engram`) are removed; files without the Engram marker are never touched.']),
  'clone-memory': topic('engram clone-memory', 'Clone active memory Markdown between workspace and global scopes.', ['Promote repository-local memories into portable global memory.', 'Bring global memories into a workspace for local review or offline use.', 'Preview the copy set before writing with `--dry-run`.', 'Route clone candidates through proposal-first save-session approval with `--metacognize`.', 'Overwrite destination copies only when the human explicitly passes `--force`.', 'Let agents accept natural wording such as "clone workspace memory to global".'], ['engram clone-memory workspace global', 'engram clone-memory global workspace --force', 'engram clone-memory workspace global --dry-run', 'engram clone-memory workspace global --metacognize', 'engram clone-memory workspace global --metacognize --dry-run', 'engram clone-memory workspace global --metacognize --force', 'engram cm workspace global', 'engram clone workspace memory to global and metacognize'], ['Only active `rules/`, `skills/`, and `knowledge/` Markdown files are cloned; archive, inbox, proposals, indexes, hashes, and vector sidecars are regenerated or left out.', 'Normal clone is mechanical: the destination memory frontmatter is rewritten to the destination scope, and destination hashes, index, graph, and eligible vector sidecar are refreshed.', '`--metacognize` is proposal-first: verified source memories become save-session candidates for the target scope, using the same approval and related-memory restructuring rules as save-session.', '`--force` cannot be used with `--metacognize` on the mechanical clone path; use numbered approval, `--dry-run`, or the metacognize force flow instead.', 'Existing destination files are skipped unless `--force` is passed on the mechanical clone path.', 'Source files must pass Engram hash verification before they are cloned or proposed. Run `engram verify` first if a file is reported unsafe.', 'Use `engram sync` after cloning global memory when you want to pull, commit, or push the global Git remote.'], ['cm']),
  sync: topic('engram sync', 'Sync global memory with Git and refresh enabled live-sync targets.', ['Pull/push shared global memory.', 'Refresh generated AGENTS.md or Cursor rule targets.', 'Keep team memory current after approved saves.'], ['engram sync', 'engram sy'], ['Live sync targets must be enabled in config.', 'Also refreshes native path rules for linked Claude/Cursor, whether or not live sync is enabled.'], ['sy']),
  workspace: topic('engram workspace', 'Manage registered workspaces and their per-workspace configuration.', ['List all registered workspaces.', 'Inspect a workspace path, its linked status, and config keys.', 'Set a per-workspace config key.', 'Unregister a workspace that no longer exists.', 'Link or unlink a workspace to control whether it appears in default lists.'], ['engram workspace list', 'engram workspace info', 'engram workspace info /path/to/project', 'engram workspace set scope global', 'engram workspace unregister /old/path', 'engram workspace link', 'engram workspace unlink', 'engram ws ls'], ['Workspaces are auto-registered when running engram commands in a directory.', 'Linked workspaces appear in default listings; unlinked workspaces are hidden unless explicitly listed.', 'Config keys use the same dotted-key allowlist as `engram config set`.', 'Per-workspace config is stored in the SQLite DB first, then exported to JSON snapshots for backward compat.'], ['ws']),
  config: topic('engram config', 'View resolved configuration or set user-level config keys.', ['Inspect the fully resolved engram configuration with source annotations.', 'Set a user-level config key that applies across all workspaces.', 'See which profiles and workspaces are registered.'], ['engram config view', 'engram config set scope global', 'engram config set load.limit 12', 'engram config set graph.enabled true', 'engram config set memory.include_author_email true', 'engram config set hooks.path_rules hook', 'engram cfg show'], ['Config view shows resolved config merged from user_config → profile → workspace_config layers.', 'Config set writes to user_config only; use `engram workspace set` for per-workspace overrides.', 'Allowed keys include dotted paths like load.limit, graph.enabled, vector.provider, etc.', 'JSON snapshots are exported after every write for backward compatibility.', '`mcp.resource_limit` (JSON config, default 20, 0-200) caps how many memories MCP `resources/list` returns besides `engram://index`; ranking is local injected + fetched usage.', '`hooks.path_rules` (`native` default, or `hook`) chooses how `applies_to` memories reach Claude: `native` emits `.claude/rules/engram` files and registers `InstructionsLoaded`; `hook` keeps the Engram `PreToolUse` hook. Re-run `engram link claude` after changing it.'], ['cfg']),
};

export function detailForTopic(rawTopic: string): CommandTopicHelp | undefined {
  const topic = rawTopic.toLowerCase().replace(/^engram\s+/, '').trim();
  return COMMAND_TOPICS[topic] ?? Object.values(COMMAND_TOPICS).find((item) => item.aliases?.includes(topic));
}

function topic(title: string, summary: string, useCases: string[], examples: string[], notes?: string[], aliases?: string[]): CommandTopicHelp {
  return { title, summary, useCases, examples, notes, aliases };
}


